output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in one-cell-wide shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file_aisle",
    "text": "A shopper must not push a cart from a normal aisle into a one-cell-wide shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_with_cart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_shelf_aisle_with_cart"
    }
  },
  {
    "id": "single_file_items_collected_without_cart",
    "text": "Items reached from a one-cell-wide shelf aisle must be collected without a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "single_file_shelf_aisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "cartless_only_in_access_aisle",
    "text": "After taking a cart, a shopper may walk without it only in the narrow shelf-access aisle or at its mouth.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_aisle_mouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "cartless_access_zone": {
          "or": [
            "single_file_shelf_aisle",
            "single_file_aisle_mouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartless_access_zone"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking_at_aisle_mouth",
    "text": "A cart parked at the mouth of a narrow shelf aisle must be retrieved before leaving the store.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle_mouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "park_cart_at_aisle_mouth": {
          "pre": {
            "and": [
              "single_file_aisle_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart_at_aisle_mouth": {
          "pre": {
            "and": [
              "single_file_aisle_mouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart_at_aisle_mouth",
      "discharge": "retrieve_cart_at_aisle_mouth"
    }
  },
  {
    "id": "parking_at_mouth_requires_access_trip",
    "text": "If a shopper sets down a cart at the mouth of a narrow shelf aisle, they are obliged to enter that narrow aisle on foot.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_aisle_mouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "park_cart_at_aisle_mouth": {
          "pre": {
            "and": [
              "single_file_aisle_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enter_single_file_shelf_aisle_on_foot": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart_at_aisle_mouth",
      "discharge": "enter_single_file_shelf_aisle_on_foot"
    }
  },
  {
    "id": "wide_shelf_picks_keep_cart",
    "text": "When taking items from shelves accessible from wider aisles, the shopper should keep the cart with them.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "wide_shelf_face": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            },
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "wide_shelf_face",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_parking_only_in_wide_clear_aisles",
    "text": "Carts may be set down only in wide clear aisles, not beside shelves or in narrow passages.",
    "abstraction": {
      "state_properties": {
        "wide_clear_aisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "set_down_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "set_down_cart",
          {
            "not": "wide_clear_aisle"
          }
        ]
      }
    }
  }
]
